export type Recipient = Readonly<{
  name: string;
  postalAddress: string;
}>;

export type ProviderRequest = Readonly<{
  shipmentId: string;
  routeCode: string;
  parcelGrams: number;
  recipient: Recipient;
  idempotencyKey: string;
}>;

export type ShippingDependencies = Readonly<{
  repository: Readonly<{
    get: (shipmentId: string) => Promise<unknown>;
    save: (shipmentId: string, record: unknown) => Promise<void>;
  }>;
  atlas: Readonly<{
    book: (request: ProviderRequest) => Promise<unknown>;
  }>;
  beacon: Readonly<{
    reserve: (request: ProviderRequest) => Promise<unknown>;
  }>;
  logger: Readonly<{
    info: (event: Record<string, unknown>) => void;
  }>;
}>;

type Provider = "atlas" | "beacon";
type RefusalReason = "unsupported_route" | "unsupported_parcel";

type Rejection = Readonly<{
  provider: Provider;
  reason: RefusalReason;
}>;

type ShipmentFields = Readonly<{
  schemaVersion: 1;
  id: string;
  routeCode: string;
  parcelGrams: number;
}>;

type QueuedShipment = ShipmentFields & Readonly<{
  state: "queued";
}>;

type DispatchedShipment = ShipmentFields & Readonly<{
  state: "dispatched";
  provider: Provider;
  bookingId: string;
  dispatchedAtMs: number;
}>;

type DeferredShipment = ShipmentFields & Readonly<{
  state: "deferred";
  nextProvider: Provider;
  retryAtMs: number;
  rejections: readonly Rejection[];
}>;

type UnavailableShipment = ShipmentFields & Readonly<{
  state: "unavailable";
  rejections: readonly Rejection[];
}>;

type StoredShipment = QueuedShipment | DispatchedShipment | DeferredShipment | UnavailableShipment;

export type PublicShipment =
  | Omit<QueuedShipment, "schemaVersion">
  | Omit<DispatchedShipment, "schemaVersion">
  | Omit<DeferredShipment, "schemaVersion">
  | Omit<UnavailableShipment, "schemaVersion">;

type AbortBody = Readonly<{
  code: "dispatch_aborted";
  shipmentId: string;
  failedAt: Provider | "repository";
  classification: "unknown_failure" | "invalid_provider_response" | "repository_failure";
  rejections: readonly Rejection[];
}>;

export type ServiceResponse = Readonly<{
  status: number;
  body:
    | PublicShipment
    | AbortBody
    | {
        code: "invalid_command" | "not_found" | "service_unavailable";
      };
}>;

type Command =
  | Readonly<{ op: "get"; shipmentId: string }>
  | Readonly<{ op: "dispatch"; shipmentId: string; nowMs: number; recipient: Recipient }>;

type ProviderOutcome =
  | Readonly<{ kind: "success"; bookingId: string }>
  | Readonly<{ kind: "refusal"; reason: RefusalReason }>
  | Readonly<{ kind: "throttle"; retryAtMs: number }>
  | Readonly<{ kind: "invalid_provider_response" }>
  | Readonly<{ kind: "unknown_failure" }>;

function isObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function isProvider(value: unknown): value is Provider {
  return value === "atlas" || value === "beacon";
}

function isRefusalReason(value: unknown): value is RefusalReason {
  return value === "unsupported_route" || value === "unsupported_parcel";
}

function isNonemptyString(value: unknown): value is string {
  return typeof value === "string" && value.length > 0;
}

function isPositiveSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value > 0;
}

function isNonnegativeSafeInteger(value: unknown): value is number {
  return typeof value === "number" && Number.isSafeInteger(value) && value >= 0;
}

function parseCommand(value: unknown): Command | undefined {
  if (!isObject(value) || !isNonemptyString(value.shipmentId)) {
    return undefined;
  }
  if (value.op === "get") {
    return { op: "get", shipmentId: value.shipmentId };
  }
  if (
    value.op !== "dispatch" ||
    !isNonnegativeSafeInteger(value.nowMs) ||
    !isObject(value.recipient) ||
    typeof value.recipient.name !== "string" ||
    value.recipient.name.trim().length === 0 ||
    typeof value.recipient.postalAddress !== "string" ||
    value.recipient.postalAddress.trim().length === 0
  ) {
    return undefined;
  }
  return {
    op: "dispatch",
    shipmentId: value.shipmentId,
    nowMs: value.nowMs,
    recipient: {
      name: value.recipient.name,
      postalAddress: value.recipient.postalAddress,
    },
  };
}

function parseRejections(value: unknown): readonly Rejection[] | undefined {
  if (!Array.isArray(value)) {
    return undefined;
  }
  const rejections: Rejection[] = [];
  for (const item of value) {
    if (!isObject(item) || !isProvider(item.provider) || !isRefusalReason(item.reason)) {
      return undefined;
    }
    rejections.push({ provider: item.provider, reason: item.reason });
  }
  return rejections;
}

function parseStoredShipment(value: unknown): StoredShipment | undefined {
  if (
    !isObject(value) ||
    value.schemaVersion !== 1 ||
    !isNonemptyString(value.id) ||
    !isNonemptyString(value.routeCode) ||
    !isPositiveSafeInteger(value.parcelGrams)
  ) {
    return undefined;
  }

  const fields = {
    schemaVersion: 1,
    id: value.id,
    routeCode: value.routeCode,
    parcelGrams: value.parcelGrams,
  } as const;

  if (value.state === "queued") {
    return { ...fields, state: "queued" };
  }
  if (
    value.state === "dispatched" &&
    isProvider(value.provider) &&
    isNonemptyString(value.bookingId) &&
    isNonnegativeSafeInteger(value.dispatchedAtMs)
  ) {
    return {
      ...fields,
      state: "dispatched",
      provider: value.provider,
      bookingId: value.bookingId,
      dispatchedAtMs: value.dispatchedAtMs,
    };
  }
  if (
    value.state === "deferred" &&
    isProvider(value.nextProvider) &&
    isNonnegativeSafeInteger(value.retryAtMs)
  ) {
    const rejections = parseRejections(value.rejections);
    if (rejections) {
      return {
        ...fields,
        state: "deferred",
        nextProvider: value.nextProvider,
        retryAtMs: value.retryAtMs,
        rejections,
      };
    }
  }
  if (value.state === "unavailable") {
    const rejections = parseRejections(value.rejections);
    if (rejections) {
      return { ...fields, state: "unavailable", rejections };
    }
  }
  return undefined;
}

function publicShipment(shipment: StoredShipment): PublicShipment {
  const fields = {
    id: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
  };
  switch (shipment.state) {
    case "queued":
      return { ...fields, state: "queued" };
    case "dispatched":
      return {
        ...fields,
        state: "dispatched",
        provider: shipment.provider,
        bookingId: shipment.bookingId,
        dispatchedAtMs: shipment.dispatchedAtMs,
      };
    case "deferred":
      return {
        ...fields,
        state: "deferred",
        nextProvider: shipment.nextProvider,
        retryAtMs: shipment.retryAtMs,
        rejections: shipment.rejections,
      };
    case "unavailable":
      return { ...fields, state: "unavailable", rejections: shipment.rejections };
  }
}

function providerRequest(shipment: StoredShipment, recipient: Recipient): ProviderRequest {
  return {
    shipmentId: shipment.id,
    routeCode: shipment.routeCode,
    parcelGrams: shipment.parcelGrams,
    recipient: {
      name: recipient.name,
      postalAddress: recipient.postalAddress,
    },
    idempotencyKey: shipment.id,
  };
}

function parseResolvedConfirmation(provider: Provider, value: unknown): ProviderOutcome {
  if (!isObject(value)) {
    return { kind: "invalid_provider_response" };
  }
  if (provider === "atlas" && isNonemptyString(value.bookingId)) {
    return { kind: "success", bookingId: value.bookingId };
  }
  if (provider === "beacon" && isNonemptyString(value.reference)) {
    return { kind: "success", bookingId: value.reference };
  }
  return { kind: "invalid_provider_response" };
}

function parseAtlasRejection(value: unknown, nowMs: number): ProviderOutcome {
  if (!isObject(value)) {
    return { kind: "unknown_failure" };
  }
  if (value.code === "cannot_ship") {
    return isRefusalReason(value.reason)
      ? { kind: "refusal", reason: value.reason }
      : { kind: "invalid_provider_response" };
  }
  if (value.code === "rate_limited") {
    return isNonnegativeSafeInteger(value.retryAtMs) && value.retryAtMs > nowMs
      ? { kind: "throttle", retryAtMs: value.retryAtMs }
      : { kind: "invalid_provider_response" };
  }
  return { kind: "unknown_failure" };
}

function parseBeaconRejection(value: unknown, nowMs: number): ProviderOutcome {
  if (!isObject(value)) {
    return { kind: "unknown_failure" };
  }
  if (value.type === "rejected") {
    return isObject(value.details) && isRefusalReason(value.details.reason)
      ? { kind: "refusal", reason: value.details.reason }
      : { kind: "invalid_provider_response" };
  }
  if (value.type === "throttled") {
    return isObject(value.details) &&
      isNonnegativeSafeInteger(value.details.retryAtMs) &&
      value.details.retryAtMs > nowMs
      ? { kind: "throttle", retryAtMs: value.details.retryAtMs }
      : { kind: "invalid_provider_response" };
  }
  return { kind: "unknown_failure" };
}

function parseProviderRejection(provider: Provider, value: unknown, nowMs: number): ProviderOutcome {
  return provider === "atlas" ? parseAtlasRejection(value, nowMs) : parseBeaconRejection(value, nowMs);
}

async function callProvider(
  dependencies: ShippingDependencies,
  provider: Provider,
  request: ProviderRequest,
  nowMs: number,
): Promise<ProviderOutcome> {
  try {
    const value =
      provider === "atlas"
        ? await dependencies.atlas.book(request)
        : await dependencies.beacon.reserve(request);
    return parseResolvedConfirmation(provider, value);
  } catch (error) {
    return parseProviderRejection(provider, error, nowMs);
  }
}

function abortResponse(
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: AbortBody["classification"],
  rejections: readonly Rejection[],
): ServiceResponse {
  return {
    status: 500,
    body: {
      code: "dispatch_aborted",
      shipmentId,
      failedAt,
      classification,
      rejections,
    },
  };
}

function emitAbort(
  dependencies: ShippingDependencies,
  shipmentId: string,
  failedAt: Provider | "repository",
  classification: AbortBody["classification"],
  rejections: readonly Rejection[],
): ServiceResponse {
  dependencies.logger.info({
    shipmentId,
    action: "aborted",
    failedAt,
    classification,
    rejections,
  });
  return abortResponse(shipmentId, failedAt, classification, rejections);
}

function sameProviderRefused(rejections: readonly Rejection[], provider: Provider): boolean {
  return rejections.some((rejection) => rejection.provider === provider);
}

function appendRejection(
  rejections: readonly Rejection[],
  provider: Provider,
  reason: RefusalReason,
): readonly Rejection[] {
  return [...rejections, { provider, reason }];
}

export function createShippingService(dependencies: ShippingDependencies) {
  async function saveDecision(
    shipmentId: string,
    record: StoredShipment,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse | undefined> {
    try {
      await dependencies.repository.save(shipmentId, record);
      return undefined;
    } catch {
      return emitAbort(dependencies, shipmentId, "repository", "repository_failure", rejections);
    }
  }

  async function commitDispatched(
    shipment: StoredShipment,
    provider: Provider,
    bookingId: string,
    nowMs: number,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const dispatched: DispatchedShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "dispatched",
      provider,
      bookingId,
      dispatchedAtMs: nowMs,
    };
    const failure = await saveDecision(shipment.id, dispatched, rejections);
    if (failure) {
      return failure;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "dispatched",
      provider,
    });
    return { status: 200, body: publicShipment(dispatched) };
  }

  async function commitDeferred(
    shipment: StoredShipment,
    provider: Provider,
    retryAtMs: number,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const deferred: DeferredShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "deferred",
      nextProvider: provider,
      retryAtMs,
      rejections,
    };
    const failure = await saveDecision(shipment.id, deferred, rejections);
    if (failure) {
      return failure;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "deferred",
      provider,
      retryAtMs,
      rejections,
    });
    return { status: 202, body: publicShipment(deferred) };
  }

  async function commitUnavailable(
    shipment: StoredShipment,
    rejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    const unavailable: UnavailableShipment = {
      schemaVersion: 1,
      id: shipment.id,
      routeCode: shipment.routeCode,
      parcelGrams: shipment.parcelGrams,
      state: "unavailable",
      rejections,
    };
    const failure = await saveDecision(shipment.id, unavailable, rejections);
    if (failure) {
      return failure;
    }
    dependencies.logger.info({
      shipmentId: shipment.id,
      action: "unavailable",
      rejections,
    });
    return { status: 422, body: publicShipment(unavailable) };
  }

  async function dispatchFrom(
    shipment: StoredShipment,
    command: Extract<Command, { op: "dispatch" }>,
    initialProvider: Provider,
    initialRejections: readonly Rejection[],
  ): Promise<ServiceResponse> {
    let provider: Provider = initialProvider;
    let rejections = initialRejections;

    for (let attempts = 0; attempts < 2; attempts += 1) {
      if (sameProviderRefused(rejections, provider)) {
        return commitUnavailable(shipment, rejections);
      }

      const outcome = await callProvider(
        dependencies,
        provider,
        providerRequest(shipment, command.recipient),
        command.nowMs,
      );

      switch (outcome.kind) {
        case "success":
          return commitDispatched(shipment, provider, outcome.bookingId, command.nowMs, rejections);
        case "throttle":
          return commitDeferred(shipment, provider, outcome.retryAtMs, rejections);
        case "invalid_provider_response":
          return emitAbort(
            dependencies,
            shipment.id,
            provider,
            "invalid_provider_response",
            rejections,
          );
        case "unknown_failure":
          return emitAbort(dependencies, shipment.id, provider, "unknown_failure", rejections);
        case "refusal": {
          rejections = appendRejection(rejections, provider, outcome.reason);
          if (provider === "atlas" && !sameProviderRefused(rejections, "beacon")) {
            provider = "beacon";
            continue;
          }
          return commitUnavailable(shipment, rejections);
        }
      }
    }

    return commitUnavailable(shipment, rejections);
  }

  async function handle(input: unknown): Promise<ServiceResponse> {
    const command = parseCommand(input);
    if (!command) {
      return { status: 400, body: { code: "invalid_command" } };
    }

    let value: unknown;
    try {
      value = await dependencies.repository.get(command.shipmentId);
    } catch {
      return emitAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }
    if (value === undefined) {
      return { status: 404, body: { code: "not_found" } };
    }

    const shipment = parseStoredShipment(value);
    if (!shipment) {
      return emitAbort(
        dependencies,
        command.shipmentId,
        "repository",
        "repository_failure",
        [],
      );
    }

    if (command.op === "get") {
      return { status: 200, body: publicShipment(shipment) };
    }

    switch (shipment.state) {
      case "queued":
        return dispatchFrom(shipment, command, "atlas", []);
      case "dispatched":
        return { status: 200, body: publicShipment(shipment) };
      case "deferred":
        if (command.nowMs < shipment.retryAtMs) {
          return { status: 202, body: publicShipment(shipment) };
        }
        return dispatchFrom(shipment, command, shipment.nextProvider, shipment.rejections);
      case "unavailable":
        return { status: 422, body: publicShipment(shipment) };
    }
  }

  return { handle };
}
